<template><div class="section"><div class="container" v-if="post"><span class="kicker">WON NYACI RUN JOURNAL</span><h1 style="max-width:900px">{{post.title}}</h1><p class="section-lead">{{post.excerpt}}</p><img v-if="post.image" :src="asset(post.image)" class="post-image" style="height:auto;max-height:520px;border-radius:25px;margin:25px 0"/><article class="rich-text" v-html="safeBody"></article><RouterLink to="/blog" class="btn btn-primary">← Back to stories</RouterLink></div><div v-else class="container"><p>Loading story…</p></div></div></template>
<script setup>import {ref,onMounted,computed} from 'vue';import {useRoute} from 'vue-router';import axios from 'axios';const route=useRoute(),post=ref(null);const asset=p=>p?.startsWith('http')?p:(p?.startsWith('images/')?`/${p}`:`/storage/${p}`);const safeBody=computed(()=>post.value?.body?.replaceAll('\n','<br>')||'');onMounted(async()=>{post.value=(await axios.get('/api/posts/'+route.params.slug)).data})</script>
<style scoped>.rich-text{font-size:18px;line-height:1.85;max-width:850px;margin:25px 0 40px}.rich-text :deep(img){max-width:100%}</style>
